var AppGreeting = (typeof window !== 'undefined' && window.AppGreeting) ? window.AppGreeting : (typeof AppGreeting !== 'undefined' ? AppGreeting : {});

// Global Tutor 360 Copilot Launcher - Abre el Centro de Tutorías y Guías Pedagógicas
