        editParcialDates(id) {
            const parcial = Store.get('parciales').find(p => p.id === id);
            if (!parcial) return;

            Swal.fire({
                title: `<span style="color: var(--text-main);"> Editar ${ parcial.nombre }</span> `,
                background: '#0A1020', /* var(--bg2) */
                color: 'var(--text-main)',
                html: `
    <div class="flex flex-col gap-4 text-left">
                                <div class="form-group mb-0">
                                    <label class="block text-sm mb-1" style="color: var(--text-muted);">Fecha Inicio</label>
                                    <input type="date" id="swal-start" class="form-control" value="${parcial.fechaInicio}" 
                                           style="background: rgba(255,255,255,0.05); border: 1px solid var(--border-glass); color: var(--text-main);">
                                </div>
                                <div class="form-group mb-0">
                                    <label class="block text-sm mb-1" style="color: var(--text-muted);">Fecha Fin</label>
                                    <input type="date" id="swal-end" class="form-control" value="${parcial.fechaFin}"
                                           style="background: rgba(255,255,255,0.05); border: 1px solid var(--border-glass); color: var(--text-main);">
                                </div>
                            </div>
    `,
                showCancelButton: true,
                confirmButtonText: 'Guardar',
                cancelButtonText: 'Cancelar',
                buttonsStyling: false,
                customClass: {
                    popup: 'card',
                    confirmButton: 'btn btn-primary ml-2',
                    cancelButton: 'btn btn-secondary'
                },
                preConfirm: () => {
                    const start = document.getElementById('swal-start').value;
                    const end = document.getElementById('swal-end').value;
                    if (!start || !end) {
                        Swal.showValidationMessage('Ambas fechas son obligatorias');
                        return false;
                    }
                    if (start > end) {
                        Swal.showValidationMessage('La fecha de inicio no puede ser posterior a la fecha fin');
                        return false;
                    }
                    return { start, end };
                }
            }).then((result) => {
                if (result.isConfirmed) {
                    Store.update('parciales', parcial.id, {
                        fechaInicio: result.value.start,
                        fechaFin: result.value.end
                    });

                    UI.toast('Fechas actualizadas');

                    // Refresh view
                    const content = Views.Evaluacion.render();
                    const contentEl = document.getElementById('content');
                    if (contentEl) {
                        contentEl.innerHTML = content;
                        if (window.lucide) window.lucide.createIcons();

                        // Restore accordion state if possible or just open the edited one
                        Views.Evaluacion.toggleParcial(parcial.id);
                    }
                }
            });
        },
        toggleParcial(id) {
            if (!this.state) this.state = { expandedParcials: {} };
            const el = document.getElementById(`dims-${id}`);
            const chevron = document.getElementById(`chevron-${id}`);
            if (el && chevron) {
                const isHidden = el.style.display === 'none';
                const newState = isHidden; // if was hidden, now is open (true)
                el.style.display = newState ? 'block' : 'none';
                chevron.style.transform = newState ? 'rotate(180deg)' : 'rotate(0deg)';
                
                // Guardamos el estado
                this.state.expandedParcials[id] = newState;
            }
        },
