                                       data-student-id="${s.id}"
                                       data-parcial-id="${p.id}"
                                       data-parcial-num="${p.numero || (cIdx + 1)}"
                                       data-dim-grade="${dimVal !== null ? dimVal : ''}"
                                       data-emg-row="${rIdx}"
                                       data-emg-col="${cIdx}"
                                       data-accent-color="${pal.accent}"
                                       data-is-desertor="${isDesertor ? 'true' : 'false'}"
